# Intermediate Query

use ecommerces;
# 1. Find all sub_category items that have generated a total Profit of more than 2,000 across all orders.
select sub_category,sum(Profit) as total_profit from order_details 
group by sub_category
having total_profit>2000;

# 2. Find the total sales Amount generated by each State, sorted from highest to lowest revenue.
select l.State,sum(o.Amount) as total_amount 
from list_of_orders as l
inner join order_details as o
on l.order_id=o.order_id
group by l.State
order by total_amount desc; 

# 3.List the top 5 unique customers who have placed the highest number of orders.
select customer_name, count(distinct order_id) as total_orders from list_of_orders
group by customer_name
order by total_orders desc
limit 5;

# 4. Calculate the average Amount for each City, showing only cities where the average Amount exceeds 300.
select l.City,avg(o.Amount) as average_amount 
from list_of_orders as l
inner join order_details as o
on l.order_id=o.order_id
group by l.city
having average_amount>300;

# 5. Find the total Profit for each State and Category combination, showing only the combinations that resulted in an overall net loss.
select l.State,o.Category, sum(o.Profit) as total
from list_of_orders as l
inner join order_details as o
on l.order_id=o.order_id
group by l.State,o.Category
having total<0;

# 6. Identify all order_ids and their corresponding customer_name where the total Quantity of items in that single order is 15 or more.
select l.order_id,l.customer_name,sum(o.Quantity) as total_quantity
from list_of_orders as l
inner join order_details as o
on l.order_id=o.order_id
group by l.order_id,l.customer_name
having total_quantity>=15;

# 7. Calculate the total Quantity sold and total Profit for each sub_category for orders shipped to 'Mumbai', 'Delhi','Bangalore', or 'Chennai', sorted by highest profit first.
select o.sub_category,sum(o.quantity) as total_quantity,sum(o.profit) as total_profit 
from list_of_orders as l
inner join order_details as o
on l.order_id=o.order_id
where l.City in ("Mumbai","Delhi","Bangalore","Chennai")
group by o.sub_category
order by total_profit desc;

# 8. Retrieve the order_id, customer_name, City, State,and total Amount for orders containing 'Furniture' items where the Furniture subtotal in that order exceeds 1,500.
select l.order_id,l.customer_name,l.city,l.state,sum(o.Amount) as total_amount
from list_of_orders as l
inner join order_details as o
on l.order_id=o.order_id
where o.Category="Furniture"
group by l.order_id,l.customer_name,l.city,l.state
having total_amount>1500;

# 9. Calculate the total target for each category in sales_target.
select category, sum(target) as total_target from sales_target
group by category;

# 10. Identify all order_ids and their customer_name having at least 2 different Category types and has an overall positive Profit.
select l.order_id, l.customer_name,count(distinct o.category) as category_count,sum(o.Profit) as total_profit
from list_of_orders as l
inner join order_details as o
on l.order_id=o.order_id
group by l.order_id, l.customer_name
having category_count>=2 and total_profit >0;
